import{z as l,x as A,o as i,c as p,q as o,j as B,D as t,d as e,s as r,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Gini 系数分解","description":"","frontmatter":{"title":"Gini 系数分解","date":"2026-09-27T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gini-decomposition.md","filePath":"econ/gini-decomposition.md","lastUpdated":1791413859000}'),d={name:"econ/gini-decomposition.md"};function D(m,a,c,_,g,C){const n=A("Mermaid");return i(),p("div",null,[a[2]||(a[2]=o('<h1 id="gini-系数分解" tabindex="-1">Gini 系数分解 <a class="header-anchor" href="#gini-系数分解" aria-label="Permalink to &quot;Gini 系数分解&quot;">​</a></h1><div class="epigraph"><p>基尼系数是一个数，不是一个诊断：拆成组间、组内与重叠三块，才知道不平等长在哪个关节上。</p><footer>—— 据 Gini (1912)；Dagum 基尼分解 (1997)；Pyatt 三方分解 (1976)</footer></div><p><a href="/econ/congestion-pricing">拥堵定价</a>的公平账要算清分配，本课给分配测量的解剖刀。基尼系数人人会算、少人会拆。缺口是<strong>基尼分解</strong>：把总不平等按子群体（组间/组内）或按收入来源（要素分解）切开，回答「政策该往哪打」。本课只讲基尼族的分解，不进泰尔熵族。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全国基尼 0.47，城乡拆开后城镇 0.42、农村 0.45、组间 0.18——三个数什么关系？为什么各组基尼之和远小于全国？拆解要回答两件事：各子群体贡献几何；分解是否可加、是否唯一。基尼的分解不完美（有重叠项），这正是要讲清的地方。</p><p><span class="marginnote">术语翻译：组间不平等 = 用各组均值算出的基尼（把组内抹平后剩下的差距）；组内 = 各组内部的基尼按人口加权；重叠（overlap/residual）= 富组里的穷人与穷组里的富人「交错」产生的项——它是基尼分解不为零的根源。</span></p><p><span class="marginnote">数字实例：城镇均值 4 万、农村 2 万，各自基尼 0.42/0.45。组间项（把每组都换成均值）约 0.14，人口加权组内项约 0.30，重叠项约 0.03——三项加总才是 0.47。重叠小（城乡几乎不交叉）时组间项才是主矛盾。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Dagum 三步：把全体按子群体分组，各 group 内排序；两两计算 \\(G_{jh}\\)——同组配对（组内贡献）与跨组配对（净差距 = 富组赢的配对减穷组赢的配对）；剩下一块就是跨组重叠强度。要素分解（另一条路）：按工资、经营、转移支付等收入来源分别算集中度 \\(C_k\\)，加权求和即总基尼——<strong>集中度</strong>与<strong>份额</strong>是两个独立的政策旋钮。</p>',9)),(i(),B(s,null,{default:t(()=>[r(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%A8%E6%A0%B7%E6%9C%AC%E6%94%B6%E5%85%A5%E6%8E%92%E5%BA%8F%22%5D%20--%3E%20B%5B%22%E6%8C%89%E5%AD%90%E7%BE%A4%E4%BD%93%E5%88%86%E7%BB%84%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%BB%84%E5%86%85%E9%85%8D%E5%AF%B9%E5%B7%AE%20%7Cyi-yj%7C%22%5D%0A%20%20B%20--%3E%20D%5B%22%E8%B7%A8%E7%BB%84%E9%85%8D%E5%AF%B9%E5%B7%AE%22%5D%0A%20%20C%20--%3E%20E%5B%22%E7%BB%84%E5%86%85%E5%9F%BA%E5%B0%BC%E5%8A%A0%E6%9D%83%22%5D%0A%20%20D%20--%3E%20F%5B%22%E7%BB%84%E9%97%B4%E5%87%80%E5%B7%AE%E8%B7%9D%20%2B%20%E9%87%8D%E5%8F%A0%E9%A1%B9%22%5D%0A%20%20E%20--%3E%20G%5B%22%E6%80%BB%E5%9F%BA%E5%B0%BC%20%3D%20%E4%B8%89%E9%A1%B9%E4%B9%8B%E5%92%8C%22%5D%0A%20%20F%20--%3E%20G%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：基尼像「全班身高差的平均值翻倍」。按班级拆：班与班的平均身高差（组间）+ 各班内部身高差（组内）+ 高个班里的矮个与矮个班里的高个交叠的部分（重叠）。三块都量出来，才知道是「班与班差太多」还是「班内太参差」。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("基尼可分解性弱于泰尔熵：\\(G = G_w + G_b + G_t\\)，重叠项 \\(G_t\\ge 0\\) 且只在子群体收入分布交错时存在——城乡几乎分层时 \\(G_t\\to 0\\)，分解近乎完美；教育扩张让城乡分布交叠加大时 \\(G_t\\) 膨胀，同样总基尼背后结构可以完全不同。要素分解的机制刀更锋利：转移支付的集中度若为负（偏向穷人），它对总基尼是"),E("strong",null,"减项"),e("；某来源集中度上升推高总基尼当且仅当其份额乘（\\(C_k-G\\)）为正。政策诊断力全在这两个乘积符号上。")],-1)),(i(),B(s,null,{default:t(()=>[r(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%94%BF%E7%AD%96%E5%BE%80%E5%93%AA%E6%89%93%3F%22%7D%20--%3E%7C%22%E7%9C%8B%E9%9B%86%E4%B8%AD%E5%BA%A6%20Ck%22%7C%20R%5B%22Ck%20%E8%B6%8A%E5%B0%8F%E8%B6%8A%E6%B5%8E%E8%B4%AB%22%5D%0A%20%20R%20--%3E%20S%5B%22%E8%BD%AC%E7%A7%BB%E6%94%AF%E4%BB%98%20Ck%3C0%3A%20%E7%9B%B4%E6%8E%A5%E9%99%8D%E5%9F%BA%E5%B0%BC%22%5D%0A%20%20T%7B%22%E7%9C%8B%E9%87%8D%E5%8F%A0%E9%A1%B9%22%7D%20--%3E%20U%5B%22Gt%20%E5%A4%A7%3A%20%E7%BB%84%E5%88%AB%E5%88%86%E5%B1%82%E5%A4%B1%E6%95%88%22%5D%0A%20%20U%20--%3E%20V%5B%22%E6%8C%89%E7%BB%84%E5%88%AB%E6%96%BD%E7%AD%96%E9%92%9D%E5%8C%96%22%5D%0A%20%20V%20--%3E%20W%5B%22%E6%94%B9%E6%8C%89%E6%9D%A5%E6%BA%90%2F%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%E6%96%BD%E7%AD%96%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：把「各组基尼的加权平均」当总基尼——漏掉组间与重叠项会系统性低估；另一误区是把要素分解与人群分解混着报——前者按收入来源切，后者按人口特征切，切法不同政策含义完全不同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基尼对分布中部敏感、尾部钝感——顶端 1% 的变化常被低估，配套要报 top-income 份额或帕累托尾部。分组数越细，组内项越大、组间项越小，跨研究比较必须固定分组口径。转移支付与税收的「再分配效应」要用<strong>市场收入基尼 vs 可支配收入基尼</strong>之差来量，混用总人口与劳动人口口径是文献常见硬伤。与<a href="/econ/capability-approach">可行能力方法</a>的接口：基尼测收入维度，能力法主张多维（教育、健康、发言权）——收入基尼低而能力剥夺高的社会并不罕见。</p><p><span class="marginnote">直觉类比：总基尼像「体检综合分」，分解是分科检查——组间项是「科室之间的差异」，组内项是「科室内部的参差」，重叠项是「两科室病人你中有我」；只看综合分开不出处方。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>基尼分解 = 组内 + 组间 + 重叠；重叠项源于跨组收入交错。</li><li>要素分解看集中度与份额：\\(C_k\\) 的符号决定某来源是加剧还是缓解。</li><li>基尼钝感尾部、依赖分组口径，配套报 top 份额与再分配两口径。</li><li>出处：Gini 1912；Pyatt 1976；Dagum 1997；World Bank Inequality Database 口径说明。</li></ul>',6))])}const f=l(d,[["render",D]]);export{h as __pageData,f as default};
